                    }
                    if (apuestaActual[0] > apuestaAnterior) {
                        Arrays.fill(yaActuo, false);
                        todosIgualaron = false;
                    }
                }
                yaActuo[indice] = true;
            }
            if (todosIgualaron) {
                return false;
            }
        }
    }

