            return true;
        }
        if ("all-in".equals(accion) || "3".equals(accion)) {
            int cantidad = jugador.getSaldo();
            aportar(jugador, cantidad, jugadores, apuestas, indice);
            jugador.setVaAllIn(true);
            apuestaActual[0] = Math.max(apuestaActual[0], apuestas[indice]);
