        view.mostrarMensaje("Ciega pequeña actual: " + smallBlind + ", Ciega grande actual: " + bigBlind);
    }

    public void aumentarCiegas() {
        contadorManos++;
        if (contadorManos % manosParaAumentarCiegas == 0) {
